import{_ as o,o as a,c as r,a4 as n}from"./chunks/framework.BBs01uty.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/node-module.md","filePath":"books/node-module.md"}'),l={name:"books/node-module.md"};function t(d,e,i,s,m,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h2 id="node模块机制" tabindex="-1">Node模块机制 <a class="header-anchor" href="#node模块机制" aria-label="Permalink to &quot;Node模块机制&quot;">​</a></h2><p>node模块实现主要基于commonjs模块机制</p><p>主要过程是：</p><ol><li>路径分析</li><li>文件定位</li><li>编译、执行</li></ol><p>nodejs模块分为三类：</p><ol><li>核心模块：js模块 &amp; c++内建模块</li><li>文件模块：js模块 &amp; c++模块</li><li>自定义模块：依赖模块(node_modules)</li></ol><h4 id="文件模块" tabindex="-1">文件模块 <a class="header-anchor" href="#文件模块" aria-label="Permalink to &quot;文件模块&quot;">​</a></h4><p>通常传入绝对或者相对路径引入文件模块，此过程会分析路径、文件定位、编译执行；js模块直接在node环境编译执行，若是.node(c++编写)的文件模块需要调用dlopen直接调用(不需要编译即可调用)，因此.node模块会比js模块更快、更高效</p><h4 id="核心模块" tabindex="-1">核心模块 <a class="header-anchor" href="#核心模块" aria-label="Permalink to &quot;核心模块&quot;">​</a></h4><p>核心模块无需进行路径分析和文件定位，直接进行编译执行即可；最底层的是c++内建模块，js核心模块实质上是对底层模块进行封装，调用过程会顺着调用栈到底层</p><h4 id="自定义模块" tabindex="-1">自定义模块 <a class="header-anchor" href="#自定义模块" aria-label="Permalink to &quot;自定义模块&quot;">​</a></h4><p>通常指外部依赖，require(模块名)之后</p><ol><li>node会检查当前目录是否存在node_modules目录，若不存在则进入上层目录查找(路径分析)</li><li>找到模块目录之后，检查是否存在package.json文件，分析package.json文件取其入口文件main定义的值；若无package,json则检查是否存在index(按照.js、.node、.json顺序匹配)，因此若文件后缀非.js建议不省略后缀</li><li>.js文件直接编译执行js代码；.node文件直接调用dlopen(动态加载)；.json文件则执行JSON.parse后将对象引入</li></ol><h4 id="包-模块-管理工具-npm" tabindex="-1">包(模块)管理工具：npm <a class="header-anchor" href="#包-模块-管理工具-npm" aria-label="Permalink to &quot;包(模块)管理工具：npm&quot;">​</a></h4><h4 id="三种现代模块机制-commonjs、cmd、amd" tabindex="-1">三种现代模块机制：commonJs、CMD、AMD <a class="header-anchor" href="#三种现代模块机制-commonjs、cmd、amd" aria-label="Permalink to &quot;三种现代模块机制：commonJs、CMD、AMD&quot;">​</a></h4><h5 id="commonjs" tabindex="-1">commonJs： <a class="header-anchor" href="#commonjs" aria-label="Permalink to &quot;commonJs：&quot;">​</a></h5><p>使用require和module.exports进行引入和导出模块，一个文件代表一个模块，所有文件执行在一个闭包函数执行，参数传require、exports(只是module.exports的一个引用，重新赋值会导致失败)、module等</p><h5 id="amd" tabindex="-1">AMD： <a class="header-anchor" href="#amd" aria-label="Permalink to &quot;AMD：&quot;">​</a></h5><p>requireJs框架的模块机制，采取依赖前置，回调函数异步定义模块，如：<code>require([dep1,dep2...], function(){...return {}})</code></p><h5 id="cmd" tabindex="-1">CMD： <a class="header-anchor" href="#cmd" aria-label="Permalink to &quot;CMD：&quot;">​</a></h5><p>seaJs提出的模块机制，定义模块同步执行，将require、exports、module传入，需要依赖时就近require</p><h4 id="未来模块机制-es6的import-export" tabindex="-1">未来模块机制：ES6的import/export <a class="header-anchor" href="#未来模块机制-es6的import-export" aria-label="Permalink to &quot;未来模块机制：ES6的import/export&quot;">​</a></h4><p>import引入的模块在编译过程中已经存储在内存中，并以一个<strong>引用</strong>提供给用户(无法更改)，其加载速度和效率高于其他模块机制</p>',23)])])}const u=o(l,[["render",t]]);export{h as __pageData,u as default};
